primaryQuery:
run: order_items -> {
  where: year(created_at) = 2022
  aggregate: total_sales is sale_price.sum()
}

verifyQuery:
run: order_items -> {
  where: created_at ? @2022
  group_by: mo is created_at.month
  aggregate: monthly_sales is sale_price.sum()
} -> { aggregate: total_sales is monthly_sales.sum() }
